window.pcSlugify = function (str) {
  return String(str || "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "")
    || ("post-" + Date.now());
};

window.pcReadStore = function (key) {
  try { return JSON.parse(localStorage.getItem(key) || "[]"); }
  catch (e) { return []; }
};

window.pcWriteStore = function (key, items) {
  try { localStorage.setItem(key, JSON.stringify(items)); } catch (e) {}
};

